Why might trajectories look flat? An interactive explainer
The paper tested four explanations for flat trajectories. Two of them can be felt directly: publication bias that is stronger for younger infants props up early effect sizes, and method adaptation (harder tasks for older infants) pushes later effect sizes down — both flatten an underlying increase. Set a true developmental slope, then apply each distortion and watch what the observed literature would show.

viewof true_slope = Inputs.range([0, 0.1], { label: "True slope (d/month)",
  step: 0.005, value: 0.05 })

viewof bias_strength = Inputs.range([0, 1], {
  label: "Age-graded publication bias", step: 0.05, value: 0 })

viewof adaptation = Inputs.range([0, 0.1], {
  label: "Method adaptation (d/month penalty)", step: 0.005, value: 0 })

viewof resample = Inputs.button("Resample studies")






























explainer = {
  resample;
  const n = 120;
  const rand_norm = () =&gt; {
    const u = Math.random() || 1e-12, v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  // simulate studies across 0-36 months
  let pts = d3.range(n).map(() =&gt; {
    const age = Math.random() * 36;
    const se = 0.15 + Math.random() * 0.25;
    const true_es = 0.1 + true_slope * age - adaptation * age;
    const obs = true_es + rand_norm() * se;
    // age-graded publication bias: young + null results get suppressed
    const sig = obs / se &gt; 1.64;
    const suppress_p = !sig ? bias_strength * Math.max(0, (36 - age) / 36) : 0;
    return { age, obs, se, published: Math.random() &gt; suppress_p };
  });
  const pub = pts.filter((d) =&gt; d.published);
  const fit = (rows) =&gt; {
    const sw = d3.sum(rows, (d) =&gt; 1 / (d.se * d.se));
    const mx = d3.sum(rows, (d) =&gt; d.age / (d.se * d.se)) / sw;
    const my = d3.sum(rows, (d) =&gt; d.obs / (d.se * d.se)) / sw;
    const b = d3.sum(rows, (d) =&gt; (d.age - mx) * (d.obs - my) / (d.se * d.se)) /
      d3.sum(rows, (d) =&gt; (d.age - mx) ** 2 / (d.se * d.se));
    return { a: my - b * mx, b };
  };
  const f = fit(pub);
  const lines = [
    { x1: 0, y1: 0.1, x2: 36, y2: 0.1 + true_slope * 36, kind: "true slope (no distortion)" },
    { x1: 0, y1: f.a, x2: 36, y2: f.a + f.b * 36, kind: "what the published literature shows" }
  ];
  return Plot.plot({
    width: 780, height: 420,
    marginLeft: 55,
    x: { label: "Mean age (months)" },
    y: { label: "Effect size (d)" },
    color: { legend: true,
             domain: ["true slope (no distortion)", "what the published literature shows"],
             range: ["#999", "#dc322f"] },
    marks: [
      Plot.ruleY([0], { strokeDasharray: "3,3", stroke: "#ccc" }),
      Plot.dot(pts, { x: "age", y: "obs", r: 3,
        fill: (d) =&gt; d.published ? "#268bd2" : "#bbb",
        fillOpacity: (d) =&gt; d.published ? 0.6 : 0.35,
        title: (d) =&gt; d.published ? "published" : "unpublished (suppressed)" }),
      ...lines.map((l) =&gt; Plot.link([l], { x1: "x1", y1: "y1", x2: "x2", y2: "y2",
        stroke: "kind", strokeWidth: 2.5,
        strokeDasharray: l.kind.startsWith("true") ? "6,4" : null }))
    ]
  });
}






