Small-study effects: sample size vs effect size
If studies with smaller samples report systematically larger effects — because small studies only reach significance (and publication) with big effects — the literature overestimates. Kendall’s τ between n and effect size per dataset (the 2018 paper’s Table 5 found significant negative correlations in 4 of 12 meta-analyses).

kendall_tau = (xs, ys) =&gt; {
  // tau-b with normal approximation p-value
  const n = xs.length;
  let concordant = 0, discordant = 0, tx = 0, ty = 0;
  for (let i = 0; i &lt; n; i++)
    for (let j = i + 1; j &lt; n; j++) {
      const dx = Math.sign(xs[i] - xs[j]), dy = Math.sign(ys[i] - ys[j]);
      if (dx === 0 && dy === 0) { tx++; ty++; }
      else if (dx === 0) tx++;
      else if (dy === 0) ty++;
      else if (dx === dy) concordant++;
      else discordant++;
    }
  const n0 = n * (n - 1) / 2;
  const tau = (concordant - discordant) /
    Math.sqrt((n0 - tx) * (n0 - ty) || 1);
  const z = 3 * (concordant - discordant) /
    Math.sqrt(n * (n - 1) * (2 * n + 5) / 2);
  const p = 2 * (1 - pnorm(Math.abs(z)));
  return { tau, p };
}

tau_rows = all_data.map(({ meta, rows }) =&gt; {
  const pts = rows
    .map((r) =&gt; ({ n: +r.n, g: +r.g_calc }))
    .filter((r) =&gt; Number.isFinite(r.n) && Number.isFinite(r.g));
  if (pts.length &lt; 10) return null;
  const { tau, p } = kendall_tau(pts.map((r) =&gt; r.n), pts.map((r) =&gt; r.g));
  return { dataset: meta.name, k: pts.length, tau, p, significant: p &lt; 0.05 && tau &lt; 0 };
}).filter(Boolean)
















