      Plot.dot(rows, { y: "dataset", x: "tau",
        fill: (d) =&gt; d.significant ? "#dc322f" : "#333", r: 4,
        title: (d) =&gt; `${d.dataset}\nτ = ${d.tau.toFixed(2)}, p = ${d.p.toFixed(3)} (k = ${d.k})`,
        tip: true })
    ]
  });
}

html`&lt;p style="font-size:0.9rem; color:#444;"&gt;Red: significantly negative
(bias-consistent) at p &lt; .05 — currently
${tau_rows.filter((d) =&gt; d.significant).length} of ${tau_rows.length}
datasets. A negative τ can also arise from accurate prospective power
analysis for subtler effects; the pervasively low power above argues
against that explanation.&lt;/p&gt;`
















